queries.kustoQuery:
let unix_epoch_start = datetime(1/1/1970);
let opids = materialize(ApiQosEvent
| where PreciseTimeStamp between((queryFrom)..queryTo)
| where operationName !contains "GET"
| where subscriptionId =~ subId
| where resourceGroupName =~ rgName
| where resourceName == resName
|where operationName !in ("AsyncOperationCompletionOperation", "VirtualMachines.RetrieveBootDiagnosticsData.POST", "VirtualMachines.RetrieveVMConsoleScreenshot.POST", "Deployments.Preflight.POST", "DiskRPCallback.AllocateDisks.POST", "VirtualMachines.RetrieveVMConsoleScreenshot.POST","CustomerSupport.RetrieveSasUri.POST", "VMScaleSetCleanupInternalOperation","NrpCallback.DeleteTenant.POST", "VirtualMachines.RetrieveVMConsoleSerialLogs.POST", "NrpCallback.FinalizeTenantResourceAllocation.POST", "NrpCallback.RevertTenantResourceAllocation.POST", "NrpCallback.DeallocateAllTenantNetworkResources.POST", "NrpCallback.AllocateTenantNetworkResources.POST", "NrpCallback.CommitTenantResourceAllocation.POST","RestorePoints.RestorePointOperation.PUT", "Subscriptions.Register.PUT", "AsyncOperationCallbackOperation", "RestorePoints.RestorePointOperation.DELETE", "RestorePoints.RetrieveSasUris.POST", "FabricCallback.OnRoleInstanceStateChange.POST", "RestorePoints.RestorePointOperation.DELETE")
| distinct  operationId);
let tenantNames = materialize (ComponentQoSEvent
| where PreciseTimeStamp between((queryFrom)..queryTo)
| where fabricTenantName != ""
| where activityId in (opids)
//|summarize min(PreciseTimeStamp),max(PreciseTimeStamp) by fabricCluster, fabricTenantName
| distinct fabricTenantName);
//| extend Content = fabricTenantName
//| extend StartTime = min_PreciseTimeStamp , EndTime = max_PreciseTimeStamp
//| distinct fabricTenantName);
cluster('azcore.centralus').database('Fc').LogTenantSnapshot //More accurate and we can get the actual fabric cluster and other details. 
| where PreciseTimeStamp between((queryFrom)..queryTo)
| where tenantName in~ (tenantNames)
//| summarize StartTime = arg_min(PreciseTimeStamp, tenantName), EndTime = arg_max(PreciseTimeStamp, tenantName)by  Cluster =  Tenant, tenantName, isSpannable, isSpanned
| summarize StartTime = arg_min(PreciseTimeStamp, tenantName)by  Cluster =  Tenant, tenantName, isSpannable, isSpanned
| extend startTimeTicks = datetime_diff("second", queryFrom, unix_epoch_start ) * 1000
| extend endTimeTicks = datetime_diff("second", queryTo, unix_epoch_start) * 1000
| extend FailoverDashBoardUrl = strcat("https://portal.microsoftgeneva.com/s/FEEEA?overrides=[{\"query\":\"//*[id='Tenant']\",\"key\":\"value\",\"replacement\":\"" , Cluster, "\"}]&globalStartTime=", startTimeTicks, "&globalEndTime=" , endTimeTicks, "&pinGlobalTimeRange=true")
| project StartTime, Content = tenantName, Cluster, isSpannable, isSpanned, FailoverDashBoardUrl

let local_subscriptionId = split(ResURI,"/")[2];
let local_resourceGroupName = split(ResURI,"/")[4];
let local_resourceName = split(ResURI,"/")[8];
let local_vmssInstanceName = split(ResURI,"/")[10];
let opids = materialize(ApiQosEvent
| where PreciseTimeStamp between(queryFrom..2h)
| where tolower(subscriptionId) == tolower(local_subscriptionId) and operationName !contains "GET"
| where tolower(resourceGroupName) == tolower(local_resourceGroupName)
| where tolower(resourceName) startswith tolower(local_resourceName) or (isnotempty(tolower(local_vmssInstanceName)) and tolower(resourceName) startswith tolower(local_vmssInstanceName)));
let ctxact = materialize(ContextActivity
| where PreciseTimeStamp between(queryFrom..2h) and activityId in (opids | project operationId)
| where message has "is requesting preemption"  or message has "Not preempting current execution as it was preempted too many times." and message !has "`1" or message has "Execution preempted for" or message has "Switching activity-id to"
| project PreciseTimeStamp, activityId, message);
opids | join kind=inner ctxact on $left.operationId == $right.activityId
| parse message with * 'Activity ' ActivityIdWhichRequestedPreemption ' ' * 'Current preemption count is ' CurrentPreemptionCount '.'
| parse message with * 'Switching activity-id to ' SwitchedToActivityId
| distinct  StartTime=(PreciseTimeStamp-e2EDurationInMilliseconds * 1ms), EndTime=PreciseTimeStamp, resultCode, operationName, resourceGroupName, resourceName, correlationId, activityId, ActivityIdWhichRequestedPreemption, CurrentPreemptionCount,SwitchedToActivityId,  requestEntity, message
| order by StartTime asc

let startTime = queryFrom;
let endTime = queryTo;
//Do not edit below this line
let FRIC_RELEASE_TIME_LIMIT = 15m; 
let CONTAINER_DESTROY_TIME_LIMIT = 15m;
let CrpOp = materialize(
    macro-expand isfuzzy=true entity_group [cluster('azcore.centralus.kusto.windows.net')] as X(
        X.database('Crp').ApiQosEvent
            | where PreciseTimeStamp between(startTime..endTime)
                and subscriptionId == subid
                and resourceGroupName =~ rgName
                and resourceName =~ resName
                and resultCode == 'NetworkingInternalOperationError'
            |extend extractCode = iif(errorDetails has 'Code: ', extract('Code: (.*)', 1, tostring(errorDetails)), '')
            | extend NRPerrortype = case (
                        extractCode in ("RnmServiceDeletionCleanupTimeout","RnmServiceInstanceCleanupTimeout"), 'FricReleaseIssue', //FRIC release issues
                            'NotComputeToBlame')
            )
        | project PreciseTimeStamp, NRPerrortype , errorDetails //, operationName, resultCode, requestEntity - will need it only when testing the query
        | top 1 by PreciseTimeStamp asc
);
let FricReleaseIssue =materialize( 
    CrpOp  
        | where NRPerrortype != 'NotComputeToBlame'
        | extend 
            extractedTenantName = iif(errorDetails has 'serviceId: ', extract('serviceId: (.*?),', 1, tostring(errorDetails)),''),
            extractedDeletedTime = iif(errorDetails has 'DeletedDateTime: ', extract('DeletedDateTime: (.*?) IsCleanupPendingInTM',1, tostring(errorDetails)),''),
            extractedFabricId = tolower(iif(errorDetails has 'FabricId: ', extract('FabricId: (.*?) PendingDeleteInFabric',1, tostring(errorDetails)),'')),
            extractedRoleInstanceName = iff(isempty(toupper(extract("Name: (.*?) ", 1, tostring(errorDetails)))),strcat("_",toupper(resName)),toupper(extract("Name: (.*?) ", 1,tostring(errorDetails)))),
            isCleanupPendingInTM = iff(errorDetails has "IsCleanupPendingInTM: True" , true, false),
            isPendingDeleteInFa = iff(errorDetails has "PendingDeleteInFabric: True", true, false),
            extractedNetworkServiceInstanceId = iif(errorDetails has "NetworkServiceInstanceId: ", extract('NetworkServiceInstanceId: ([a-fA-F0-9]{8}[-]?([a-fA-F0-9]{4}[-]?){3}[a-fA-F0-9]{12})', 1, tostring(errorDetails)),'') 
            //We have the scenario where the vip is stuck associated with a ghost tenant so this helps to confirm
        | extend extractedVipReleasePending = iff(errorDetails contains "VipReleasePendingInRnmBeforeNsmQuery",true,false)
        | extend extractedVipReleasePendingNsm = iff( errorDetails contains 'VipReleasePendingInNsmPlus',true,false)
        // We just want to focus on the scenario where RNM/NSM blames Compute
        | where isCleanupPendingInTM or isPendingDeleteInFa
);
let nsId = toscalar(FricReleaseIssue | project extractedNetworkServiceInstanceId);
let StartRNMcheck = todatetime(toscalar(FricReleaseIssue | project extractedDeletedTime));
let tenantNameFromCrP=(FricReleaseIssue | project extractedTenantName);
//Check Rnm Release notification state
FricReleaseIssue
    | join kind = leftouter (
        macro-expand isfuzzy=false entity_group [cluster('azcore.centralus.kusto.windows.net')] as X(
            X.database("AzureCP").AzSMTenantStatemachineEvents
            | where PreciseTimeStamp between(todatetime(StartRNMcheck) ..now())
                and tenantName in (tenantNameFromCrP) and isnotempty(tenantName)
                | project PreciseTimeStamp, tenantName , stateMachineId , stateMachineState , message 
                | where * contains "rnm"
        )
    ) on $left.extractedTenantName==$right.tenantName
    | project PreciseTimeStamp, tenantName, stateMachineId, stateMachineState, message

